$output=Join-Path $repoRoot 'validation/evidence/ni-final-validation.json'
$encoding=New-Object Text.UTF8Encoding($false,$true)
function Read-Doc([string]$p){[IO.File]::ReadAllText((Join-Path $repoRoot $p))}
function Hash-Bytes([byte[]]$b){$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash($b))).Replace('-','').ToLower()}finally{$s.Dispose()}}
function Sections([string]$t){$m=[regex]::Matches($t,'(?m)^#{1,4} (\d{1,2})\. [^\r\n]+');$r=@{};for($i=0;$i -lt $m.Count;$i++){$end=if($i+1 -lt $m.Count){$m[$i+1].Index}else{$t.Length};$r[[int]$m[$i].Groups[1].Value]=$t.Substring($m[$i].Index,$end-$m[$i].Index).Replace("`r`n","`n").Trim()};$r}
function Criteria([string]$t,[int]$section){$p=(Sections $t)[$section];$m=[regex]::Matches($p,'(?m)^#{2,4}\s+AC-(\d{2})[^\r\n]*');$r=@{};if(-not $m.Count){foreach($v in [regex]::Matches($p,'(?m)^\|\s*AC-(\d{2})\s*\|\s*(.*?)\s*\|\s*$')){$r[[int]$v.Groups[1].Value]=$v.Groups[2].Value};return $r};for($i=0;$i -lt $m.Count;$i++){$end=if($i+1 -lt $m.Count){$m[$i+1].Index}else{$p.Length};$r[[int]$m[$i].Groups[1].Value]=$p.Substring($m[$i].Index,$end-$m[$i].Index).Trim()};$r}
