$allowedNew=@('governance/mandates/m01-consolidated-mandate-1.0.md','governance/mandates/m01-consolidated-mandate-1.1.md','governance/mandates/m01-consolidated-mandate-1.0-to-1.1-redline.md','governance/mandates/m01-consolidated-mandate-1.0-to-1.1.diff','governance/reviews/cto-execution-continuation-02.md','governance/reviews/cto-m01-normative-review-02.md','governance/sources/cto-source-transfer-02-manifest.md','governance/sources/m01-presidential-deliberation-01.md','validation/evidence/ni-complement-intake.json','validation/evidence/ni-final-baseline.json','validation/evidence/ni-reconciliation.json','validation/evidence/ni-final-validation.json','validation/VAL-NORMATIVE-INTEGRATION-FINAL-01.md','validation/validate-normative-integration-final.ps1','status/NI-FINAL-DELIVERY-HANDOFF.md')
$preserved=@();if(@($baseline.files).Count -ne 79){$issues.Add('Baseline não contém os 79 arquivos iniciais')}
foreach($f in $baseline.files){$p=Join-Path $repoRoot $f.path;if(-not (Test-Path -LiteralPath $p)){$issues.Add('Arquivo inicial excluído: '+$f.path);continue};if($f.path -notin $allowedModified){$sha=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLower();$same=$sha -eq $f.sha256;$preserved+=[ordered]@{path=$f.path;before_sha256=$f.sha256;after_sha256=$sha;unchanged=$same};if(-not $same){$issues.Add('Arquivo histórico/fonte alterado: '+$f.path)}}}
Add-Type -AssemblyName System.IO.Compression.FileSystem
if(-not ('AncestralidadeFinalCrc32' -as [type])){Add-Type -TypeDefinition 'public static class AncestralidadeFinalCrc32 { public static uint Compute(byte[] a) { uint c=0xffffffffu; foreach(byte b in a){c^=b; for(int i=0;i<8;i++)c=(c&1u)!=0?0xedb88320u^(c>>1):c>>1;} return c^0xffffffffu;} }'}
$zipBytes=[IO.File]::ReadAllBytes($ArchivePath);$zipHash=Hash-Bytes $zipBytes
if($zipHash -ne $intake.archive_sha256){$issues.Add('ZIP diverge do intake')}
$end=-1;for($i=$zipBytes.Length-22;$i -ge [Math]::Max(0,$zipBytes.Length-65557);$i--){if([BitConverter]::ToUInt32($zipBytes,$i) -eq 0x06054b50){$end=$i;break}};if($end -lt 0){throw 'ZIP sem diretório central'}
$count=[BitConverter]::ToUInt16($zipBytes,$end+10);$offset=[int][BitConverter]::ToUInt32($zipBytes,$end+16);$crcs=@{}
for($i=0;$i -lt $count;$i++){if([BitConverter]::ToUInt32($zipBytes,$offset) -ne 0x02014b50){throw 'Diretório central inválido'};$nl=[BitConverter]::ToUInt16($zipBytes,$offset+28);$xl=[BitConverter]::ToUInt16($zipBytes,$offset+30);$cl=[BitConverter]::ToUInt16($zipBytes,$offset+32);$name=$encoding.GetString($zipBytes,$offset+46,$nl);$crcs[$name]=[BitConverter]::ToUInt32($zipBytes,$offset+16);$offset+=46+$nl+$xl+$cl}
$archive=[IO.Compression.ZipFile]::OpenRead($ArchivePath);$zipResults=@();$texts=@{}
try{if($archive.Entries.Count -ne 4 -or $count -ne 4){$issues.Add('Pacote não contém quatro entradas')};foreach($entry in $archive.Entries){$r=$intake.entries|Where-Object entry -eq $entry.FullName;if(-not $r){throw 'Entrada não autorizada no ZIP'};$s=$entry.Open();$mem=New-Object IO.MemoryStream;try{$s.CopyTo($mem);$bytes=$mem.ToArray()}finally{$s.Dispose();$mem.Dispose()};$text=$encoding.GetString($bytes);$sha=Hash-Bytes $bytes;$crc=[AncestralidadeFinalCrc32]::Compute($bytes);$copy=Read-Doc $r.canonical_path;$canonicalSha=(Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $repoRoot $r.canonical_path)).Hash.ToLower();$lines=($text -split "`n").Count;if($text.EndsWith("`n")){$lines--};$pass=$crc -eq $crcs[$entry.FullName] -and $sha -eq $r.source_sha256 -and $bytes.Length -eq $r.bytes -and $lines -eq $r.lines -and $canonicalSha -eq $r.canonical_sha256 -and $copy.EndsWith($text);if(-not $pass){$issues.Add('Integridade/cópia divergente: '+$entry.FullName)};$zipResults+=[ordered]@{entry=$entry.FullName;bytes=$bytes.Length;lines=$lines;sha256=$sha;crc32=('{0:x8}' -f $crc);crc_pass=($crc -eq $crcs[$entry.FullName]);utf8_strict_pass=$true;canonical_sha256=$canonicalSha;payload_preserved=$copy.EndsWith($text);result=$(if($pass){'PASS'}else{'FAIL'})};$texts[$entry.FullName]=$text}}
finally{$archive.Dispose()}
$receivedManifest=$texts['SOURCE-MANIFEST.md'];foreach($r in $intake.entries|Where-Object entry -ne 'SOURCE-MANIFEST.md'){if(-not $receivedManifest.Contains($r.source_sha256)){$issues.Add('Hash não consta no manifesto recebido: '+$r.entry)}}
$source06=$texts['SOURCE-06-CONSOLIDATED-MANDATE-1.0.md'];$draft=Read-Doc 'governance/mandates/m01-consolidated-mandate-1.1.md';$before=Sections $source06;$after=Sections $draft
if($before.Count -ne 36 -or $after.Count -ne 36){$issues.Add('Consolidado não preserva 36 seções')}
$actuallyChanged=@();$actuallyUnchanged=@();foreach($n in 1..36){if($before[$n] -ceq $after[$n]){$actuallyUnchanged+=$n}else{$actuallyChanged+=$n}}
if(($actuallyChanged -join ',') -ne ($maps.changed_sections -join ',')){$issues.Add('Redline/seções modificadas divergem da matriz')}
$oldT01=$before[10].Substring($before[10].IndexOf('Fica estabelecida'));$newT01=$after[10].Substring($after[10].IndexOf('Fica estabelecida'));if($oldT01 -cne $newT01){$issues.Add('Corpo normativo T01 não foi preservado')}
if($before[5] -cne $after[5]){$issues.Add('Tabela DEC-01–16 foi modificada')}
$original=Read-Doc 'governance/sources/m01-mvp-original-mandate-01.md';$construction=Read-Doc 'governance/sources/m01-directory-construction-mandate-01.md'
$originalAC=Criteria $original 27;$constructionAC=Criteria $construction 20;$oldAC=Criteria $source06 24;$newAC=Criteria $draft 24
if($originalAC.Count -ne 18 -or $constructionAC.Count -ne 26 -or $oldAC.Count -ne 18 -or $newAC.Count -ne 18){$issues.Add('Contagens dos três namespaces incorretas')}
if($maps.forward_ac.Count -ne 18 -or $maps.reverse_ac.Count -ne 18 -or $maps.construction_ac.Count -ne 26 -or $maps.original_sections.Count -ne 32 -or $maps.consolidated_sections.Count -ne 36 -or $maps.decisions.Count -ne 16){$issues.Add('Matriz incompleta')}
$classifications=@('PRESERVED','EXPANDED','REDISTRIBUTED','SUPERSEDED_BY_APPROVED_DECISION','GAP','CONFLICT','UNRESOLVED')
foreach($i in 1..18){$m=$maps.forward_ac|Where-Object source -eq ('MVP:AC-{0:00}' -f $i);if(@($m).Count -ne 1){$issues.Add('Origem MVP sem mapeamento único: '+$i);continue};if($m.source_text.Replace("`r`n","`n").Trim() -cne $originalAC[$i] -or $m.baseline_1_0_text.Replace("`r`n","`n").Trim() -cne $oldAC[$i] -or $m.draft_1_1_text.Replace("`r`n","`n").Trim() -cne $newAC[$i]){$issues.Add('Texto da comparação diverge de fonte/destino: '+$m.source)};if($m.classification -notin $classifications -or -not $m.requirement -or -not $m.decision -or -not $m.impact -or -not $m.authority -or -not $m.disposition){$issues.Add('Campos insuficientes na comparação: '+$m.source)};$inverse=$maps.reverse_ac|Where-Object {$_.source -eq $m.target -and $_.target -eq $m.source};if(@($inverse).Count -ne 1){$issues.Add('Cobertura inversa ausente: '+$m.source)}}
foreach($i in 1..26){$m=$maps.construction_ac|Where-Object source -eq ('CONSTRUCTION:AC-{0:00}' -f $i);if($m.source_text -cne $constructionAC[$i] -or $m.status -ne 'PROPOSED_FOR_EXECUTIVE_AUTHORIZATION'){$issues.Add('Construção alterada/promovida: '+$i)}}
foreach($m in $maps.original_sections){if($m.classification -notin $classifications -or -not $m.draft_sections.Count){$issues.Add('Seção original sem correspondência válida')}}
foreach($m in $maps.consolidated_sections){if(-not $m.mvp_source_sections.Count -and -not $m.additional_basis){$issues.Add('Seção consolidada sem base de autoridade')}}
$trace=Read-Doc 'validation/M01-NORMATIVE-TRACEABILITY.md';foreach($i in 1..14){if(-not $trace.Contains(('R{0:00}' -f $i))){$issues.Add('Requisito ausente da matriz: '+$i)}};foreach($i in 1..16){if(-not $trace.Contains(('DEC-{0:00}' -f $i))){$issues.Add('DEC ausente da matriz: '+$i)}}
$canonicalPath='governance/sources/normative-integration-mandate-01.md';$blob=(& git -C $repoRoot rev-parse ($checkpoint+':'+$canonicalPath)).Trim();$req=Read-Doc $canonicalPath
if($blob -ne $intake.reference_resolution.remote_git_blob -or $blob -ne $intake.reference_resolution.local_git_blob -or -not $req.Contains('ANCESTRALIDADE-REQ-NORMATIVE-INTEGRATION-01') -or -not $texts['SOURCE-09-CTO-NORMATIVE-REVIEW-02.md'].Contains($checkpoint+'/'+$canonicalPath)){$issues.Add('Referência canônica SOURCE-09 não resolvida')}
$diff=Read-Doc 'governance/mandates/m01-consolidated-mandate-1.0-to-1.1.diff';if($diff -notmatch '(?m)^@@ ' -or $diff -notmatch '(?m)^\+.*AC-01' -or $diff -notmatch '(?m)^-.*AC-01'){$issues.Add('Redline vazio/incompleto')}
$docs=@(Get-ChildItem -Recurse -File -LiteralPath $repoRoot -Filter '*.md'|Where-Object {$_.FullName -notmatch '[\\/]\.git[\\/]' });$ids=@{};$referenceCount=0;$metadata=@()
foreach($f in $docs){$rel=$f.FullName.Substring($repoRoot.Length+1).Replace('\','/');$t=[IO.File]::ReadAllText($f.FullName);$header=[regex]::Match($t,'(?s)\A---\r?\n(.*?)\r?\n---\r?\n');if(-not $header.Success){$issues.Add('Frontmatter ausente: '+$rel);continue};$h=$header.Groups[1].Value;foreach($key in @('id','title','version','status','authority','maintainer','module','classification','references','supersedes','last_updated')){if($h -notmatch ('(?m)^'+$key+':')){$issues.Add('Metadado ausente: '+$rel+'/'+$key)}};$id=[regex]::Match($h,'(?m)^id:\s*(\S+)').Groups[1].Value;if($ids.ContainsKey($id)){$issues.Add('ID duplicado: '+$id)}else{$ids[$id]=$rel};if($h -notmatch '(?m)^classification: PUBLIC\s*$'){$issues.Add('Classificação requer tratamento antes de publicação: '+$rel)};if($t.Contains([char]0xFFFD)){$issues.Add('Decodificação inválida: '+$rel)};if(([regex]::Matches($t,'(?m)^```').Count % 2) -ne 0){$issues.Add('Code fence ímpar: '+$rel)}
 $targets=@([regex]::Matches($t.Substring($header.Length),'\]\(([^)]+)\)')|ForEach-Object{$_.Groups[1].Value});$targets+=@([regex]::Matches($h,'(?m)^  - "([^"\r\n]+)"\s*$')|ForEach-Object{$_.Groups[1].Value});foreach($target in $targets){if($target -match '^(https?:|mailto:|#)'){continue};$referenceCount++;$resolved=[IO.Path]::GetFullPath((Join-Path $f.DirectoryName (($target.Trim('<','>') -split '#',2)[0])));if($resolved -ne $output -and -not (Test-Path -LiteralPath $resolved)){$issues.Add('Referência inexistente: '+$rel+' -> '+$target)}}
 foreach($pattern in @('gh[pousr]_[A-Za-z0-9]{30,}','github_pat_[A-Za-z0-9_]{40,}','AKIA[0-9A-Z]{16}','-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----','\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b','\b\d{3}\.\d{3}\.\d{3}-\d{2}\b','C:[\\/]Users[\\/]')){if([regex]::IsMatch($t,$pattern,[Text.RegularExpressions.RegexOptions]::IgnoreCase)){$issues.Add('Padrão sensível, conteúdo omitido: '+$rel)}}
 if($rel -in $allowedModified){$initial=(& git -C $repoRoot show ($checkpoint+':'+$rel)) -join "`n";$previous=[regex]::Match($initial,'(?m)^version: "([^"]+)"').Groups[1].Value;$v=$previous.Split('.');$expected=$v[0]+'.'+([int]$v[1]+1);$version=[regex]::Match($h,'(?m)^version: "([^"]+)"').Groups[1].Value;if($version -ne $expected -or -not $h.Contains($checkpoint+':'+$rel+'@'+$previous)){$issues.Add('Versão/proveniência anterior incorreta: '+$rel)}}
 if($rel -in $allowedModified -or $rel -in $allowedNew){$metadata+=[ordered]@{path=$rel;id=$id;version=[regex]::Match($h,'(?m)^version: "([^"]+)"').Groups[1].Value;status=[regex]::Match($h,'(?m)^status:\s*(\S+)').Groups[1].Value}}
}
$manifest=Read-Doc 'governance/SOURCE-MANIFEST.md';foreach($r in $intake.entries){if(-not $manifest.Contains($r.source_sha256) -or -not $manifest.Contains($r.canonical_sha256)){$issues.Add('Hash ausente do manifesto corrente: '+$r.entry)}}
$state=Read-Doc 'status/CURRENT-STATUS.md';foreach($v in @('9/9','7/7','NI-G01 PASS','PENDING','NOT_DEFINED','C10','OPEN','AC-KF-03-R1','BLOCKED','NOT_FROZEN','NOT_ESTABLISHED','CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW')){if(-not ($state.Replace('**','')).Contains($v)){$issues.Add('Estado corrente incompleto: '+$v)}}
if($draft -notmatch '(?m)^presidential_ratification: PENDING' -or $draft -notmatch '(?m)^status: PREPARED_FOR_CTO_REVIEW_AND_PRESIDENTIAL_RATIFICATION' -or $draft -notmatch '(?m)^supersedes: null'){$issues.Add('Minuta promovida prematuramente')}
$val=Read-Doc 'validation/VAL-NORMATIVE-INTEGRATION-FINAL-01.md';$criteria=@([regex]::Matches($val,'(?m)^\| (AC-NI-\d{2}) \|[^\r\n]*? \| (PASS|FAIL|BLOCKED|NOT_EXECUTED) \|')|ForEach-Object{[ordered]@{id=$_.Groups[1].Value;result=$_.Groups[2].Value}});$counts=@{};foreach($v in @('PASS','FAIL','BLOCKED','NOT_EXECUTED')){$counts[$v]=@($criteria|Where-Object result -eq $v).Count};if($criteria.Count -ne 16 -or $counts.PASS -ne 16){$issues.Add('Matriz AC-NI final não contém 16 resultados documentais PASS')}
$head=(& git -C $repoRoot rev-parse HEAD).Trim();$branch=(& git -C $repoRoot branch --show-current).Trim();if($head -ne $checkpoint -or $branch -ne 'dev'){$issues.Add('HEAD/branch alterados')};if((& git -C $repoRoot diff --cached --name-only)){$issues.Add('Index contém alterações staged')}
$modified=@(& git -C $repoRoot diff --name-only);$new=@(& git -C $repoRoot ls-files --others --exclude-standard);foreach($p in @($modified)+@($new)){if($p -notin $allowedModified -and $p -notin $allowedNew){$issues.Add('Arquivo fora de escopo: '+$p)}}
$result=[ordered]@{id='ANCESTRALIDADE-VAL-NI-FINAL-LOCAL-RESULT';date='2026-11-27';executor='AGENT_CODER';checkpoint=$checkpoint;head=$head;branch=$branch;initial_working_tree=$baseline.initial_working_tree;archive=@{sha256=$zipHash;entries=$zipResults;crc_errors=@($zipResults|Where-Object crc_pass -ne $true).Count;utf8_strict='PASS'};reference_resolution=$intake.reference_resolution;NI_G01='PASS';required_sources='9/9';essential_sources='7/7';markdown_files=$docs.Count;unique_ids=$ids.Count;references_checked=$referenceCount;preserved_files=$preserved.Count;preservation=$preserved;modified=$modified;new=$new;metadata=$metadata;traceability=@{mvp_forward=18;consolidated_reverse=18;construction_proposed=26;original_sections=32;consolidated_sections=36;decisions=16;changed_sections=$actuallyChanged;unchanged_sections=$actuallyUnchanged;T01_normative_body_unchanged=($oldT01 -ceq $newT01);DEC_section_unchanged=($before[5] -ceq $after[5]);unmapped=0};ac_ni=$criteria;counts=$counts;application_tests='NOT_EXECUTED';historical_validators_reexecuted=$false;cto_tests_attributed_to_agent=$false;revision_1_1='PREPARED_FOR_CTO_REVIEW_AND_PRESIDENTIAL_RATIFICATION';presidential_ratification='PENDING';C10='OPEN';AC_KF_03_R1='BLOCKED';engineering_readiness='NOT_ESTABLISHED';errors=@($issues);result=$(if($issues.Count){'FAIL'}else{'PASS'});next_gate='CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW';limitations=@('Checks establish received-byte integrity and documentary coverage, not historical binary identity or a signature','No runtime, provider, legal or financial qualification','No independent remote recovery of uncommitted revision 1.1','Metadata/links/pattern checks are not a complete YAML parser, renderer or sensitive-data audit','Baseline byte hashes may differ in another checkout due to line-ending normalization')}
[IO.File]::WriteAllText($output,($result|ConvertTo-Json -Depth 14),(New-Object Text.UTF8Encoding($false)))
[pscustomobject]@{result=$result.result;markdown_files=$docs.Count;references_checked=$referenceCount;preserved_files=$preserved.Count;counts=$counts;errors=@($issues)}|ConvertTo-Json -Depth 5
